Let $A = \lbrack\begin{matrix}
a & b \\
0 & c
\end{matrix}\rbrack,A^{2} = \lbrack\begin{matrix}
a^{2} & ab + bc \\
0 & c^{2}
\end{matrix}\rbrack$
$A^{3} = \lbrack\begin{matrix}
a^{3} & a^{2}b + abc + bc^{2} \\
0 & c^{3}
\end{matrix}\rbrack$
$A^{3} = \lbrack\begin{matrix}
8 & - 57 \\
0 & 27
\end{matrix}\rbrack$
$a^{3} = 8{\ \ \ \ \ \ \ \ \ \ \ \ c}^{3} = 27\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ a^{2}b + abc + bc^{2} = - 57$
$a = 2\ \ \ \ \ \ \ \ \ \ \ \ \ \ c = 3\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ b = - 3$

